CREATE OR REPLACE FUNCTION public.protect_ranked_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and new.status='published' then return new; end if;
 if exists(select 1 from public.popular_rankings r where r.division=case when tg_table_name='techniques' then 'technique' else 'theory' end and r.content_ids ? old.id) then
  raise exception '人気ランキングに掲載中です。先にランキングの記事を差し替えてください。' using errcode='23514';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_theory_legacy_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status='published' then
    if new.display_id is null then
      raise exception '公開理論には表示IDが必要です。' using errcode='23514';
    end if;
    new.display_order:=new.display_id;
    new.draft_display_id:=null;
  else
    new.display_id:=null;
    new.display_order:=null;
    if new.status='archived' then new.draft_display_id:=null; end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_theory_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare category_name text;
begin
 select title into category_name from public.content_categories where kind='theory' and id=new.category_id;
 if category_name is null then raise exception '理論カテゴリを選択してください。' using errcode='22023'; end if;
 new.category_title:=category_name;
 if new.category_id='practical-wisdom' and new.status='draft' and new.provenance is null then
  new.provenance:='{"status":"オリジナル","attribution":"処世術禄","works":["処世術禄オリジナル"],"sources":[],"note":"処世術禄によるオリジナルの実践知です。"}'::jsonb;
 end if;
 if new.status='published' and (nullif(trim(new.title),'') is null or nullif(trim(new.summary),'') is null) then
  raise exception 'タイトルと概要は公開に必須です。' using errcode='22023';
 end if;
 if jsonb_typeof(new.aliases)<>'array' or jsonb_typeof(new.related_theory_ids)<>'array' then raise exception '別名と関連理論の形式が不正です。' using errcode='22023'; end if;
 if new.related_theory_ids ? new.id then raise exception '自分自身を関連理論に指定できません。' using errcode='22023'; end if;
 if new.provenance is not null then
  if coalesce(new.provenance->>'status','') not in ('オリジナル','確認済み','書誌確認済み','一部確認','出典不明') then raise exception '出典状態を選択してください。' using errcode='22023'; end if;
  if jsonb_typeof(coalesce(new.provenance->'sources','[]'::jsonb))<>'array' then raise exception '参照先の形式が不正です。' using errcode='22023'; end if;
  if exists(select 1 from jsonb_array_elements(coalesce(new.provenance->'sources','[]')) s where coalesce(s->>'url','') !~ '^https://[^[:space:]]+$' or nullif(trim(s->>'title'),'') is null) then raise exception '参照先には名称とhttpsのURLを入力してください。' using errcode='22023'; end if;
 end if;
 if new.category_id='practical-wisdom' and new.status='published' then
  if new.title !~ '^「[^「」]+」$' or new.provenance is null
    or new.provenance->>'status' is distinct from 'オリジナル'
    or new.provenance->>'attribution' is distinct from '処世術禄'
    or new.provenance->'works' is distinct from '["処世術禄オリジナル"]'::jsonb
    or new.provenance->>'note' is distinct from '処世術禄によるオリジナルの実践知です。'
    or coalesce(new.provenance->'sources','[]'::jsonb)<>'[]'::jsonb
    or nullif(new.provenance->>'period','') is not null then
   raise exception '実践知は「」形式のタイトルと処世術禄オリジナルの出典を設定してください。' using errcode='22023';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_theory_relations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare linked_id text;
begin
 if new.status<>'published' then
   if exists(select 1 from public.techniques where status<>'archived' and theory_ids ? new.id)
   or exists(select 1 from public.technique_drafts d join public.techniques t on t.id=d.technique_id
     where t.status<>'archived' and (d.snapshot->'theory_ids') ? new.id)
   or exists(select 1 from public.theories where status='published' and id<>new.id and related_theory_ids ? new.id) then
     raise exception 'この理論は処世術・下書き・関連理論から参照されています。先に関連を外してください。' using errcode='23503';
   end if;
   return new;
 end if;
 for linked_id in select jsonb_array_elements_text(new.related_theory_ids) loop
   perform 1 from public.theories where id=linked_id and status='published' for share;
   if not found then raise exception '公開中の関連理論を選択してください。' using errcode='23503'; end if;
 end loop;
 return new;
end $function$
